-- Each row is check_name, violations. All values must be zero.
SELECT 'invalid_edition_path' AS check_name, COUNT(*) AS violations FROM course_edition ce LEFT JOIN study_path sp ON sp.id=ce.study_path_id AND sp.institution_id=ce.institution_id WHERE sp.id IS NULL
UNION ALL SELECT 'invalid_campus_link',COUNT(*) FROM course_edition_campus ec LEFT JOIN course_edition ce ON ce.id=ec.course_edition_id AND ce.institution_id=ec.institution_id LEFT JOIN campus c ON c.id=ec.campus_id AND c.institution_id=ec.institution_id WHERE ce.id IS NULL OR c.id IS NULL
UNION ALL SELECT 'invalid_enrollment',COUNT(*) FROM student_enrollment se LEFT JOIN student s ON s.id=se.student_id AND s.institution_id=se.institution_id LEFT JOIN course_edition ce ON ce.id=se.course_edition_id AND ce.institution_id=se.institution_id WHERE s.id IS NULL OR ce.id IS NULL
UNION ALL SELECT 'invalid_class_path',COUNT(*) FROM class c LEFT JOIN course_edition ce ON ce.id=c.course_edition_id AND ce.institution_id=c.institution_id LEFT JOIN biennium_study_path bsp ON bsp.id=c.biennium_study_path_id AND bsp.institution_id=c.institution_id WHERE c.course_edition_id IS NOT NULL AND (ce.id IS NULL OR bsp.id IS NULL OR ce.study_path_id<>bsp.study_path_id)
UNION ALL SELECT 'invalid_edition_state_dates',COUNT(*) FROM course_edition WHERE BINARY status NOT IN ('planned','active','completed','cancelled') OR start_date>end_date OR YEAR(start_date)<1000 OR YEAR(end_date)<1000 OR code NOT REGEXP '[^[:space:]]' OR name NOT REGEXP '[^[:space:]]'
UNION ALL SELECT 'invalid_enrollment_state_dates',COUNT(*) FROM student_enrollment WHERE BINARY status NOT IN ('enrolled','completed','withdrawn','cancelled') OR completion_date<enrollment_date OR YEAR(enrollment_date)<1000
UNION ALL SELECT 'missing_restrict_fk',ABS(7-COUNT(*)) FROM information_schema.referential_constraints WHERE constraint_schema=DATABASE() AND constraint_name IN ('fk_mt4_edition_owner','fk_mt4_edition_path','fk_mt4_ec_edition','fk_mt4_ec_campus','fk_mt4_enrollment_student','fk_mt4_enrollment_edition','fk_mt4_class_edition') AND delete_rule='RESTRICT' AND update_rule='RESTRICT';
